// Validate and format contract_id
const input = $input.all()[0].json;
const contractId = input.contract_id || input.body?.contract_id || input.query?.contract_id || (input.body && typeof input.body === 'string' ? JSON.parse(input.body).contract_id : null);

if (!contractId || contractId === '' || contractId === 'null' || contractId === null || contractId === undefined) {
  throw new Error('contract_id is required and cannot be empty. Received: ' + JSON.stringify(input));
}

return {
  json: {
    contract_id: String(contractId).trim()
  }
};

// Format data for approval workflow
const contract = $node['Get Contract Details'].json || {};
const workflowLevels = $node['Get Workflow Levels'].json || [];

function getValidUserId(...ids) {
  for (const id of ids) {
    if (id !== null && id !== undefined && id !== 0 && id !== '0' && id !== '') {
      const numId = Number(id);
      if (!isNaN(numId) && numId > 0) {
        return numId;
      }
    }
  }
  return null;
}

const userId = getValidUserId(contract.creator_id, contract.created_by_id);
const totalSteps = Array.isArray(workflowLevels) ? workflowLevels.length : 0;
const firstLevel = Array.isArray(workflowLevels) && workflowLevels.length > 0 ? workflowLevels[0] : null;

return {
  json: {
    document_type: 'contract',
    document_id: contract.id,
    workflow_name: `Contract Approval - ${contract.contract_number || 'N/A'}`,
    total_steps: totalSteps || 1,
    current_step: 1,
    created_by_id: userId,
    assigned_to_id: userId,
    status: 'in_progress',
    contract_id: contract.id,
    contract_number: contract.contract_number,
    creator_id: contract.creator_id || contract.created_by_id || null,
    creator_name: contract.creator_name,
    creator_email: contract.creator_email,
    total_amount: contract.total_amount,
    workflow_levels: workflowLevels,
    current_level: firstLevel,
    current_level_number: firstLevel ? firstLevel.level_number : 1,
    current_level_role: firstLevel ? firstLevel.role_id : null,
    current_level_name: firstLevel ? firstLevel.level_name : 'Level 1'
  }
};

// Generate approval token
const crypto = require('crypto');
const token = crypto.randomBytes(32).toString('hex');
const levelData = $node['Format Approval Data'].json || {};
const currentLevel = levelData.current_level || {};
const timeoutHours = currentLevel.timeout_hours || 48;
const approver = $json[0] || {};

const expiryDate = new Date();
expiryDate.setHours(expiryDate.getHours() + timeoutHours);

return {
  json: {
    approval_token: token,
    expiry_date: expiryDate.toISOString(),
    workflow_id: $node['Create Approval Workflow'].json.id,
    contract_id: $node['Get Contract Details'].json.id,
    contract_number: $node['Get Contract Details'].json.contract_number,
    approver_id: approver.id,
    approver_email: approver.email,
    approver_name: approver.full_name,
    approver_username: approver.username || approver.email?.split('@')[0] || 'approver',
    approver_role: approver.role,
    creator_name: $node['Get Contract Details'].json.creator_name,
    creator_email: $node['Get Contract Details'].json.creator_email,
    total_amount: $node['Get Contract Details'].json.total_amount,
    level: levelData.current_level_number || 1,
    level_name: levelData.current_level_name || 'Level 1',
    timeout_hours: timeoutHours
  }
};

// Format Mattermost message for contract approval
const tokenData = $node['Generate Approval Token'].json || {};

return {
  json: {
    text: `📄 **Contract Approval Required**\n\nA new contract requires your approval at ${tokenData.level_name || 'Level 1'}.`,
    channel: '#contracts-approvals',
    attachments: [
      {
        color: '#4ECDC4',
        title: `Contract ${tokenData.contract_number || 'N/A'}`,
        text: 'Please review and take action on this contract approval request.',
        fields: [
          {
            short: true,
            title: 'Contract Number',
            value: tokenData.contract_number || 'N/A'
          },
          {
            short: true,
            title: 'Amount',
            value: tokenData.total_amount ? `${tokenData.total_amount.toLocaleString('vi-VN')} VND` : 'N/A'
          },
          {
            short: true,
            title: 'Created by',
            value: tokenData.creator_name || 'Unknown'
          },
          {
            short: true,
            title: 'Approver',
            value: `@${tokenData.approver_username || 'manager'}`
          },
          {
            short: true,
            title: 'Level',
            value: `${tokenData.level_name || 'Level 1'} (Level ${tokenData.level || 1})`
          },
          {
            short: true,
            title: 'Expires in',
            value: `${tokenData.timeout_hours || 48} hours`
          }
        ],
        actions: [
          {
            name: 'Approve',
            integration: {
              url: `http://localhost:5678/webhook/contract-approval-decision?token=${tokenData.approval_token}&decision=approved`,
              context: {
                token: tokenData.approval_token,
                decision: 'approved'
              }
            }
          },
          {
            name: 'Reject',
            integration: {
              url: `http://localhost:5678/webhook/contract-approval-decision?token=${tokenData.approval_token}&decision=rejected`,
              context: {
                token: tokenData.approval_token,
                decision: 'rejected'
              }
            }
          }
        ],
        footer: 'OrientClassicsManager',
        ts: Math.floor(Date.now() / 1000)
      }
    ]
  }
};

// Format response
const contractDetails = $node['Get Contract Details']?.json || {};
const approvalToken = $node['Generate Approval Token']?.json || {};

return {
  json: {
    success: true,
    message: 'Contract approval request sent to Level 1 approver',
    contract_id: contractDetails.id || contractDetails.contract_id,
    contract_number: contractDetails.contract_number || 'N/A',
    approver: approvalToken.approver_name || 'Manager',
    workflow_id: $node['Create Approval Workflow']?.json?.id || null,
    approval_token: approvalToken.approval_token || null,
    mattermost_sent: true
  }
};
